import{_ as t,o,c as i,ae as r}from"./chunks/framework.BX6FPmO9.js";const h=JSON.parse('{"title":"References 設計系統","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/design-system-references.md","filePath":"architecture/design-system-references.md"}'),n={name:"architecture/design-system-references.md"};function a(s,e,l,c,d,p){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="references-設計系統" tabindex="-1">References 設計系統 <a class="header-anchor" href="#references-設計系統" aria-label="Permalink to &quot;References 設計系統&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：2</p><p>本專案採用 <strong>reference-based 設計系統</strong>：不直接將外部 UI kit 的程式碼或 token 當作唯一來源，而是<strong>在 repo 內維護單一實作層</strong>（tokens、primitives、patterns），同時在文件中明確標註參考來源，方便日後更換或擴充工具庫。</p><p>設計系統整體說明見：</p><ul><li><a href="./design-system.html">design-system</a> — Design System 與半自動化 UI、骨架 vs 視覺／UI kit</li><li><a href="./../DESIGN_SYSTEM.html">DESIGN_SYSTEM.md</a> — Design tokens、Core components、Usage guidelines、Token Source of Truth</li></ul><hr><h2 id="一、reference-based-設計系統的前提" tabindex="-1">一、Reference-based 設計系統的前提 <a class="header-anchor" href="#一、reference-based-設計系統的前提" aria-label="Permalink to &quot;一、Reference-based 設計系統的前提&quot;">​</a></h2><ul><li><strong>單一實作層</strong>：不論參考多少外部 UI kit，<strong>程式碼實作一律以本 repo 為準</strong>。 <ul><li>Tokens：實作於 <code>app/tailwind.css</code> 與預留的 <code>app/styles/themes/*</code>。</li><li>Primitives：實作於 <code>app/components/ui/*</code>。</li><li>Patterns：實作於 <code>app/components/shared/*</code>（例如 chat、lui 等）。</li></ul></li><li><strong>外部 kit 僅作「參考」</strong>：Figma 檔、UI kit 文件、樣式範例只作為設計／產品參考；不得直接變成第二套 primitives 或獨立 token source。</li><li><strong>Token canonical 在 repo</strong>：token 與變數的 canonical 位置在 repo（見 <a href="./../DESIGN_SYSTEM.html">DESIGN_SYSTEM.md</a> 的「Token Source of Truth」），Figma 僅提供 context。Figma MCP 僅讀取設計稿與 variables，不直接修改 layout 或新增 primitives，詳見 <a href="./figma-mcp.html">figma-mcp</a>。</li></ul><hr><h2 id="二、三個主要參考來源與對應" tabindex="-1">二、三個主要參考來源與對應 <a class="header-anchor" href="#二、三個主要參考來源與對應" aria-label="Permalink to &quot;二、三個主要參考來源與對應&quot;">​</a></h2><p>本專案目前的 reference 設計系統由三個維度組成：<strong>Tokens、Primitives、Patterns</strong>。</p><h3 id="_1-tokens-參考-untitled-ui-style-foundation" tabindex="-1">1. Tokens 參考：Untitled UI（style foundation） <a class="header-anchor" href="#_1-tokens-參考-untitled-ui-style-foundation" aria-label="Permalink to &quot;1. Tokens 參考：Untitled UI（style foundation）&quot;">​</a></h3><ul><li><strong>角色</strong>：提供色彩系統、灰階階層、spacing、radius 等「風格基礎」參考。</li><li><strong>實作位置</strong>： <ul><li><code>app/tailwind.css</code>：目前預設 theme（<code>:root</code> / <code>.dark</code>）的 CSS 變數與 Tailwind 設定。</li><li><code>app/styles/themes/*</code>：預留多 theme／多 kit 視覺，例如 <code>untitled.css</code>。</li></ul></li><li><strong>原則</strong>： <ul><li>僅將 Untitled UI 的 tokens 作為「設計參考」，轉寫為本 repo 的 CSS 變數與 Tailwind config。</li><li>不直接複製 Untitled 的 token 命名；需經過 <strong>Token Transformation Layer</strong> 與命名策略整理（見 <a href="./figma-mcp.html">figma-mcp</a>）。</li><li>新增或調整 token 時，需更新 DESIGN_SYSTEM.md 與相關 theme 檔，並可搭配 lint 或 CI 檢查。</li></ul></li></ul><h3 id="_2-primitives-參考-shadcn-ui-code-components" tabindex="-1">2. Primitives 參考：shadcn/ui（code components） <a class="header-anchor" href="#_2-primitives-參考-shadcn-ui-code-components" aria-label="Permalink to &quot;2. Primitives 參考：shadcn/ui（code components）&quot;">​</a></h3><ul><li><strong>角色</strong>：作為 React + Tailwind 的 <strong>唯一 primitive 元件來源</strong>，提供 Button、Card、Input、Alert 等 UI primitives。</li><li><strong>實作位置</strong>： <ul><li><code>app/components/ui/*</code>：所有 primitives 均在此維護。</li></ul></li><li><strong>原則</strong>： <ul><li>嚴格遵守 <a href="./../conventions/coding-conventions.html">coding-conventions</a> 與 <a href="./design-system.html">design-system</a> 中的「骨架」定義：<code>ui/*</code> 為骨架層，<strong>不隨 UI kit 或 theme 更換而改動</strong>。</li><li>外部 UI kit 不得在 <code>ui/*</code> 下新增第二套 Button / Card 等 primitives，避免分裂與治理困難。</li><li>若某 kit 需要特殊外觀，優先透過 theme（tokens）或 <code>app/components/theme/*</code> 的 wrapper 實現。</li></ul></li></ul><h3 id="_3-pattern-參考-nocra-ai-ui-kit-layout、ux" tabindex="-1">3. Pattern 參考：Nocra / AI UI kit（layout、UX） <a class="header-anchor" href="#_3-pattern-參考-nocra-ai-ui-kit-layout、ux" aria-label="Permalink to &quot;3. Pattern 參考：Nocra / AI UI kit（layout、UX）&quot;">​</a></h3><ul><li><strong>角色</strong>：提供 AI Chat / Agent UI、SaaS dashboard、空狀態與 onboarding 等「畫面模式」與 UX 範本。</li><li><strong>實作位置</strong>： <ul><li><code>app/components/shared/chat/*</code>、<code>app/components/shared/lui/*</code> 等，依實際 domain 分類。</li></ul></li><li><strong>原則</strong>： <ul><li>Patterns 僅由 primitives 和 shared 元件組合而成，不直接引入外部 kit 的程式碼。</li><li>Pattern 層專注於「結構與互動」，視覺風格則交由 tokens 與 theme 控制。</li><li>AI Chat / Agent UI pattern 的專屬規則可集中在對應的 shared 目錄與 docs/product 中說明。</li></ul></li></ul><hr><h2 id="三、未來擴充其他-ui-kit-的方式" tabindex="-1">三、未來擴充其他 UI kit 的方式 <a class="header-anchor" href="#三、未來擴充其他-ui-kit-的方式" aria-label="Permalink to &quot;三、未來擴充其他 UI kit 的方式&quot;">​</a></h2><p>當需要導入新的 UI kit（例如 Flowbite、其他 SaaS kit）時，流程建議如下：</p><ol><li><strong>文件先行</strong>：在本檔或新節點中加入該 kit 的 reference 條目，說明其擅長面向（如表格、表單、導航）。</li><li><strong>Tokens 對應</strong>： <ul><li>盤點該 kit 的 color / spacing / radius / shadow tokens。</li><li>透過 Token Transformation Layer（可配合 Figma MCP 或手動 mapping）將其轉為本 repo 的 CSS 變數與 Tailwind 設定。</li><li>在 <code>app/styles/themes/</code> 中新增對應 theme 檔（例如 <code>flowbite.css</code>），以 <code>[data-theme=&quot;flowbite&quot;]</code> 包裹覆寫。</li></ul></li><li><strong>Patterns 對應</strong>： <ul><li>從該 kit 的 Figma / 文件中抽取常見畫面（列表、表單 wizard、統計總覽等）。</li><li>使用既有 <code>ui/*</code> primitives 與 shared 元件組裝出相近 layout，不新增第二套 primitives。</li></ul></li><li><strong>實作與驗證</strong>： <ul><li>在 docs 中記錄 token 對應表與 pattern 對照。</li><li>新增最小 demo route 或 component 展示該 kit 視覺下的代表頁（類似 Hybrid Workspace demo 的 SaaS 視圖）。</li></ul></li></ol><hr><h2 id="四、元件與檔案命名原則-與-references-對齊" tabindex="-1">四、元件與檔案命名原則（與 references 對齊） <a class="header-anchor" href="#四、元件與檔案命名原則-與-references-對齊" aria-label="Permalink to &quot;四、元件與檔案命名原則（與 references 對齊）&quot;">​</a></h2><ul><li><strong>資料夾</strong>：<code>app/</code> 下（除 <code>app/routes</code>）一律小寫、無連字號與底線（例如 <code>ui</code>、<code>shared</code>、<code>workspace</code>、<code>theme</code>）。</li><li><strong>元件檔</strong>：<code>*.tsx</code> 使用 PascalCase，例如 <code>WorkspaceViewSwitcher.tsx</code>、<code>ChatInterface.tsx</code>，與本 repo coding conventions 一致。</li><li><strong>分層放置</strong>： <ul><li>primitives → <code>app/components/ui/*</code></li><li>kit surface / wrapper → <code>app/components/theme/*</code></li><li>semantics / patterns → <code>app/components/shared/*</code></li><li>app-level 組合（例如 hybrid workspace 容器）→ <code>app/components/app/*</code></li></ul></li></ul><p>詳見：</p><ul><li><a href="./../conventions/coding-conventions.html">coding-conventions</a></li><li><a href="./repo-layers.html">repo-layers</a></li></ul><hr><h2 id="五、與-hybrid-workspace-demo-的關係" tabindex="-1">五、與 Hybrid Workspace Demo 的關係 <a class="header-anchor" href="#五、與-hybrid-workspace-demo-的關係" aria-label="Permalink to &quot;五、與 Hybrid Workspace Demo 的關係&quot;">​</a></h2><p>Hybrid Workspace 首頁 demo 是此 reference-based 設計系統的一個 <strong>示範場景</strong>：</p><ul><li>同一組 primitives（<code>app/components/ui/*</code>）、同一組 shared 元件（例如 ChatInterface），</li><li>透過 <strong>不同 theme</strong>（default vs Untitled 風格）與 layout pattern，呈現： <ul><li><strong>AI Chat 為主</strong> 的 LUI 視圖。</li><li><strong>SaaS Untitled UI 風格為主</strong> 的 dashboard 視圖。</li></ul></li></ul><p>二者共用相同骨架，僅在 tokens 與 layout pattern 上有所差異，有助於驗證「UI kit 可換、骨架不換」的架構與治理策略。</p>',31)])])}const m=t(n,[["render",a]]);export{h as __pageData,m as default};
